"""Build static articles. Run `python posts\\build.py` from the repository root."""

from dataclasses import dataclass
from datetime import date
from html import escape
from pathlib import Path
import re
import sys

from markdown_it import MarkdownIt
import yaml


POSTS_DIR = Path(__file__).resolve().parent
GENERATED_MARKER = (
    "<!-- Generated by posts/build.py; edit posts/template.html or posts/content instead. -->"
)
PLACEHOLDER = re.compile(r"{{\s*(\w+)\s*}}")


@dataclass
class Post:
    id: str
    title: str
    description: str
    body: str
    published: date = date.min


def read_post(path):
    text = path.read_text(encoding="utf-8-sig")
    front_matter = re.match(r"\A---[ \t]*\r?\n(.*?)\r?\n---[ \t]*(?:\r?\n|\Z)", text, re.S)
    if not front_matter:
        raise ValueError(f"{path.name}: expected YAML metadata between opening --- lines.")
    try:
        metadata = yaml.safe_load(front_matter[1])
    except yaml.YAMLError as error:
        raise ValueError(f"{path.name}: invalid YAML metadata: {error}") from error
    if not isinstance(metadata, dict):
        raise ValueError(f"{path.name}: metadata must be a YAML mapping.")
    if not isinstance(metadata.get("draft", False), bool):
        raise ValueError(f"{path.name}: draft must be true or false (without quotes).")
    if metadata.get("draft", False):
        return None

    for key in ("id", "title", "description"):
        if not isinstance(metadata.get(key), str) or not metadata[key].strip():
            raise ValueError(f"{path.name}: {key} must be a non-empty string.")
    post_id = metadata["id"]
    if not re.fullmatch(r"[a-z0-9]+(?:[-_][a-z0-9]+)*", post_id):
        raise ValueError(f"{path.name}: id must use lowercase letters, numbers, hyphens or underscores.")
    if re.fullmatch(r"con|prn|aux|nul|com[1-9]|lpt[1-9]", post_id):
        raise ValueError(f"{path.name}: id is a reserved Windows folder name.")

    published = date.min
    if "date" in metadata:
        try:
            if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", str(metadata["date"])):
                raise ValueError("Invalid date format")
            published = date.fromisoformat(str(metadata["date"]))
        except ValueError as error:
            raise ValueError(f"{path.name}: date must use YYYY-MM-DD.") from error

    body = text[front_matter.end():].strip()
    if not body:
        raise ValueError(f"{path.name}: article body is empty.")
    return Post(post_id, metadata["title"].strip(), metadata["description"].strip(), body, published)


def time_html(published):
    if published == date.min:
        return ""
    label = published.strftime("%B %d, %Y").replace(" 0", " ")
    return f'<time datetime="{published.isoformat()}">{label}</time>'


def render_page(template, title, description, content, root, published=date.min):
    values = {
        "title": escape(title, quote=True),
        "description": escape(description, quote=True),
        "content": content,
        "root": root,
        "date": f'<p class="post-date">{time_html(published)}</p>' if published != date.min else "",
    }
    return PLACEHOLDER.sub(lambda match: values[match[1]], template)


def build(content_dir=POSTS_DIR / "content", template_path=POSTS_DIR / "template.html",
          output_dir=POSTS_DIR.parent / "docs" / "posts"):
    sources = sorted(content_dir.glob("*.md"))
    if not sources:
        raise ValueError(f"No Markdown files found in {content_dir}.")
    template = template_path.read_text(encoding="utf-8")
    placeholders = set(PLACEHOLDER.findall(template))
    expected = {"title", "description", "content", "root", "date"}
    if placeholders != expected or GENERATED_MARKER not in template:
        raise ValueError(
            "Template must retain the generated-file comment and placeholders: "
            + ", ".join(sorted(expected))
        )

    posts = []
    seen = set()
    for source in sources:
        post = read_post(source)
        if post is None:
            continue
        if post.id in seen:
            raise ValueError(f"{source.name}: duplicate article id '{post.id}'.")
        seen.add(post.id)
        posts.append(post)
    # Dated posts come first, newest first; undated posts retain filename order.
    posts.sort(key=lambda post: post.published, reverse=True)

    markdown = MarkdownIt("commonmark").enable(["table", "strikethrough"])
    pages = {}
    items = []
    for post in posts:
        tokens = markdown.parse(post.body)
        # Existing articles repeat their metadata title as a leading Markdown H1.
        if tokens and tokens[0].type == "heading_open" and tokens[0].tag == "h1":
            tokens = tokens[3:]
        content = markdown.renderer.render(tokens, markdown.options, {})
        pages[post.id] = render_page(
            template, post.title, post.description, content, "../../", post.published
        )
        items.append(
            f'<li><a href="{post.id}/">{escape(post.title)}</a>'
            f'{time_html(post.published)}<p>{escape(post.description)}</p></li>'
        )
    index = render_page(
        template, "Articles", "Learn how Centauri was designed, built, and tested.",
        '<ul class="post-list">\n' + "\n".join(items) + "\n</ul>", "../"
    )

    # Validate everything before changing published files.
    for post_id in pages:
        folder = output_dir / post_id
        if folder.is_symlink() or folder.resolve().parent != output_dir.resolve():
            raise ValueError(f"Refusing to write outside the posts folder: {folder}")
        target = folder / "index.html"
        if target.is_symlink():
            raise ValueError(f"Refusing to overwrite a symbolic link: {target}")
        if target.exists() and GENERATED_MARKER.encode() not in target.read_bytes():
            raise ValueError(f"Refusing to overwrite a non-generated article: {target}")

    output_dir.mkdir(parents=True, exist_ok=True)
    for post_id, page in pages.items():
        folder = output_dir / post_id
        folder.mkdir(exist_ok=True)
        (folder / "index.html").write_text(page, encoding="utf-8")
        print(f"Built {post_id}/index.html")
    (output_dir / "index.html").write_text(index, encoding="utf-8")

    # Remove only our generated pages for deleted, renamed, or newly drafted posts.
    for folder in output_dir.iterdir():
        if not folder.is_dir() or folder.is_symlink() or folder.name in pages:
            continue
        target = folder / "index.html"
        if target.is_file() and not target.is_symlink():
            if GENERATED_MARKER.encode() in target.read_bytes():
                target.unlink()
                print(f"Removed stale generated page: {folder.name}/index.html")
                if not any(folder.iterdir()):
                    folder.rmdir()
    print(f"Built {len(posts)} articles and posts/index.html.")


if __name__ == "__main__":
    try:
        build()
    except (OSError, ValueError) as error:
        print(f"Build failed: {error}", file=sys.stderr)
        sys.exit(1)